public sealed class WorkChannel
{
    private readonly Channel<ProcessOrderCommand> _channel =
        Channel.CreateBounded<ProcessOrderCommand>(new BoundedChannelOptions(500)
        {
            FullMode = BoundedChannelFullMode.Wait // backpressure
        });

    public ChannelWriter<ProcessOrderCommand> Writer => _channel.Writer;
    public ChannelReader<ProcessOrderCommand> Reader => _channel.Reader;
}

builder.Services.AddSingleton<WorkChannel>();
builder.Services.AddHostedService<ChannelConsumer>();

public sealed class ChannelConsumer(
    WorkChannel work,
    IServiceScopeFactory scopes) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        await foreach (var cmd in work.Reader.ReadAllAsync(ct))
        {
            await using var scope = scopes.CreateAsyncScope();
            var handler = scope.ServiceProvider.GetRequiredService<IOrderProcessor>();
            await handler.ProcessAsync(cmd, ct);
        }
    }
}

app.MapPost("/orders", async (CreateOrderRequest req, IAmazonSQS sqs, IOptions<SqsOptions> opts, CancellationToken ct) =>
{
    var orderId = Guid.NewGuid();
    var body = JsonSerializer.Serialize(new OrderCreatedEvent(orderId, req.CustomerId));

    await sqs.SendMessageAsync(new SendMessageRequest
    {
        QueueUrl = opts.Value.OrderQueueUrl,
        MessageBody = body,
        MessageGroupId = req.CustomerId.ToString(), // FIFO only
        MessageDeduplicationId = orderId.ToString()
    }, ct);

    return Results.Accepted($"/orders/{orderId}", new { orderId });
});

public sealed class SqsOrderConsumer(
    IAmazonSQS sqs,
    IOptions<SqsOptions> opts,
    IServiceScopeFactory scopes,
    ILogger<SqsOrderConsumer> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            var response = await sqs.ReceiveMessageAsync(new ReceiveMessageRequest
            {
                QueueUrl = opts.Value.OrderQueueUrl,
                MaxNumberOfMessages = 10,
                WaitTimeSeconds = 20,
                VisibilityTimeout = 60
            }, ct);

            foreach (var msg in response.Messages)
            {
                try
                {
                    await using var scope = scopes.CreateAsyncScope();
                    var processor = scope.ServiceProvider.GetRequiredService<IOrderProcessor>();
                    var evt = JsonSerializer.Deserialize<OrderCreatedEvent>(msg.Body)!;
                    await processor.ProcessIdempotentAsync(evt, ct); // upsert by orderId
                    await sqs.DeleteMessageAsync(opts.Value.OrderQueueUrl, msg.ReceiptHandle, ct);
                }
                catch (Exception ex)
                {
                    logger.LogError(ex, "Failed message {MessageId}", msg.MessageId);
                    // do not delete — visibility timeout expires, retry or DLQ
                }
            }
        }
    }
}

